#![no_std]
#![no_main]

mod sound_card;

use rmk::macros::rmk_keyboard;

// The keyboard comes from keyboard.toml (written by ../gen_firmware.py); the sound card's power from src/sound_card.rs.
// Vial config is automatically generated by `build.rs`, according to `vial.json`
// Please put `vial.json` at your project's root
#[rmk_keyboard]
mod keyboard {
    // `use` items are hoisted to the crate root by the macro; other items (structs, impls) are dropped,
    // so the processor lives in src/sound_card.rs.
    use crate::sound_card::SoundCard;

    // The body is pasted into the generated `main` (after chip init), so `p` (the embassy-rp peripherals) is in scope.
    // The pins are the board's (pcb/circuit.py RP_FIXED; ../gen_firmware.py checks them): GPIO12 the sound card's
    // supply switch, GPIO13 the amplifier's EN, GPIO29 (ADC3) VBUS through the divider.
    #[register_processor(event)]
    fn sound_card() -> SoundCard {
        SoundCard::new(
            ::embassy_rp::gpio::Output::new(p.PIN_12, ::embassy_rp::gpio::Level::Low),
            ::embassy_rp::gpio::Output::new(p.PIN_13, ::embassy_rp::gpio::Level::Low),
            ::embassy_rp::adc::Adc::new_blocking(p.ADC, ::embassy_rp::adc::Config::default()),
            ::embassy_rp::adc::Channel::new_pin(p.PIN_29, ::embassy_rp::gpio::Pull::None),
        )
    }
}
